[RequiresUnreferencedCode("Uses reflection to map handlers.")]
public void RegisterHandlers<[DynamicallyAccessedMembers(DynamicallyAccessedMemberTypes.PublicMethods)] T>()
{
    foreach (var method in typeof(T).GetMethods())
        _routes[method.Name] = method;
}
